    text: `नमस्तुलसि कल्याणि नमो विष्णुप्रिये शुभे।
नमो मोक्षप्रदे देवि नमः सम्पत्प्रदायिके।।1।।

अर्थ: कल्याणकारी, विष्णु-प्रिया, शुभ, मोक्ष देने वाली और सम्पत्ति प्रदान करने वाली हे तुलसी देवि! आपको नमस्कार।

तुलसि श्रीसखि शुभे पापहारिणि पुण्यदे।
नमस्ते नारदनुते नारायणमनःप्रिये।।2।।

अर्थ: श्री की सखी, पाप-हारिणी, पुण्य-दायिनी, नारद-स्तुता और नारायण के मन की प्रिया हे तुलसी! आपको नमस्कार।

विश्वपावनि विष्णुप्रिये तुलसि त्वं परायणम्।
सर्वपापहरे देवि विष्णुलोकप्रदायिनी।।3।।

अर्थ: विश्वपावनी, विष्णुप्रिया, सर्वपापहारी और विष्णुलोक प्रदान करने वाली हे तुलसी देवि! आपको नमन।

हरिभक्तिप्रदे देवि सुखसम्पत्प्रदायिके।
तुलसि त्वं महाभागे कृष्णलोकप्रदायिनी।।4।।

अर्थ: हरिभक्ति, सुख और सम्पत्ति प्रदान करने वाली और कृष्णलोक देने वाली हे महाभागा तुलसी! आपको नमन।

यां दृष्ट्वा पापिनो मर्त्या मुच्यन्ते सर्वकिल्बिषैः।
स्पर्शात्तारयते जन्तून्नमस्तस्यै नमो नमः।।5।।

अर्थ: जिनके दर्शन मात्र से पापी मनुष्य सभी पापों से मुक्त हो जाते हैं और स्पर्श से जीवों का उद्धार होता है, उन तुलसी देवी को बारंबार नमस्कार।

तुलस्याः पत्रमादाय पूजयेद् यो जनार्दनम्।
स सर्वपातकैर्मुक्तो विष्णुलोकं स गच्छति।।6।।

अर्थ: जो तुलसी-पत्र लेकर जनार्दन की पूजा करता है, वह सभी पापों से मुक्त होकर विष्णुलोक को प्राप्त करता है।

तुलसीकाननं यत्र यत्र पादो हरेः स्थितः।
तत्र सर्वाणि तीर्थानि प्रयागादीनि सन्ति हि।।7।।

अर्थ: जहाँ तुलसी-वन है और जहाँ भगवान हरि के चरण हैं, वहाँ प्रयाग आदि सभी तीर्थ विद्यमान हैं।

तुलस्यष्टकमेतत् पुण्यं यः पठेत् भक्तिमान् नरः।
स सर्वपापविनिर्मुक्तो वैकुण्ठं स समाप्नुयात्।।8।।

अर्थ: इस पवित्र तुलसी अष्टकम को जो भक्तिपूर्वक पढ़ता है, वह सभी पापों से मुक्त होकर वैकुण्ठ को प्राप्त करता है।

इति श्रीतुलसी अष्टकं सम्पूर्णम्।`,
