    id: "shri-narayana-ashtakam-2",
    name: "श्री नारायण अष्टकम",
    deity: "भगवान श्री नारायण",
    deityInfo:
      "भगवान नारायण विष्णु का परम रूप हैं जो क्षीरसागर में शेषनाग पर विराजित हैं। नारायण का अर्थ है सबके आश्रय-दाता। वे जगत के परम कारण, परमात्मा और मोक्षदाता हैं। चार भुजाओं में शंख, चक्र, गदा और पद्म धारण करने वाले श्री नारायण की उपासना मोक्ष का मार्ग है।",
    benefits:
      "श्री नारायण अष्टकम के पाठ से भगवान नारायण की कृपा प्राप्त होती है। जन्म-मृत्यु के चक्र से मुक्ति मिलती है। सभी पाप और कर्म-बंधन नष्ट होते हैं। वैकुण्ठ-प्राप्ति का मार्ग प्रशस्त होता है।",
    meaning:
      "इस अष्टकम के आठ श्लोकों में भगवान नारायण के स्वरूप, उनके गुणों और उनकी कृपा का गुणगान किया गया है।",
    text: `नारायण नारायण जय गोविन्द हरे।
नारायण नारायण जय गोपाल हरे।।1।।

अर्थ: हे नारायण! हे गोविंद! हे हरि! हे गोपाल! आपकी जय हो।

क्षीराब्धौ शयनं भजे श्रियापतिं देवम्।
अनन्त-शयन-शोभितं श्री-नारायणं वन्दे।।2।।

अर्थ: क्षीरसागर में शयन करने वाले, श्री के पति देव, अनंतशेष पर शोभायमान श्री नारायण की वंदना करता हूँ।

शंख-चक्र-गदा-पद्म-धारिणं पीतवाससम्।
श्रीवत्सांकितवक्षस्थं नारायणमहं भजे।।3।।

अर्थ: शंख, चक्र, गदा और पद्म धारण करने वाले, पीत वस्त्र पहने और श्रीवत्स-चिह्न से युक्त नारायण को मैं भजता हूँ।

कमला-मनोहर-नयन करुणाकर जगत्पते।
देवा-सुर-नर-मुनि-पूजित नारायण नमोऽस्तु ते।।4।।

अर्थ: कमल के समान मनोहर नेत्रों वाले, करुणा के आगार, जगत के पति, सबके द्वारा पूजित नारायण! आपको नमस्कार।

सर्वलोक-शरण्याय सर्वभूत-हितार्थिने।
पीड़ितानां परित्राणे नारायण नमोऽस्तु ते।।5।।

अर्थ: सभी लोकों के शरण-दाता, सभी प्राणियों के हित चाहने वाले और पीड़ितों के रक्षक नारायण! नमस्कार।

अनादि-मध्य-निधनं परं ब्रह्म सनातनम्।
सच्चिदानन्द-रूपाय नारायण नमोऽस्तु ते।।6।।

अर्थ: आदि, मध्य और अंत से रहित, परम ब्रह्म, सनातन और सच्चिदानंद-स्वरूप नारायण! नमस्कार।

भव-भय-हारिणे नमः परम-पुरुषाय ते नमः।
मोक्ष-मुक्ति-दायिने नारायण नमोऽस्तु ते।।7।।

अर्थ: संसार-भय को हरने वाले, परम-पुरुष और मोक्ष-मुक्ति प्रदान करने वाले नारायण! बारंबार नमस्कार।

नारायणाष्टकमिदं यः पठेत् भक्तिमान् नरः।
स सर्वपापविनिर्मुक्तो नारायण-पदं लभेत्।।8।।

अर्थ: इस नारायण अष्टकम को जो भक्तिपूर्वक पढ़ता है, वह सभी पापों से मुक्त होकर नारायण का परमपद प्राप्त करता है।

इति श्रीनारायण अष्टकं सम्पूर्णम्।`,
