    deityInfo:
      "राधाकुंड वृंदावन के समीप गोवर्धन पर्वत के पास स्थित एक पवित्र सरोवर है। यह श्री राधारानी का प्रिय स्थान माना जाता है। जीव गोस्वामी ने इसे सर्वोच्च तीर्थ बताया है और गौड़ीय वैष्णव संप्रदाय में इसकी विशेष महिमा है।",
    benefits:
      "श्री राधाकुंड अष्टकम के पाठ से राधारानी और श्रीकृष्ण की प्रेम-भक्ति प्राप्त होती है। राधाकुंड में स्नान के समान फल मिलता है। भव-सागर से मुक्ति और वृंदावन-धाम की प्राप्ति होती है।",
    meaning: "",
    text: `श्रीराधाकुण्डमखिलामरतारकं यत्
श्रीकृष्णचित्तरमणं परमं पवित्रम्।
श्रीकृष्णभक्तिनिलयं वरदं मुरारे-
र्गोविन्दसागर-तटे नतिरस्तु तस्मै।।1।।

अर्थ: समस्त देवताओं को तारने वाला, श्रीकृष्ण के चित्त को प्रसन्न करने वाला, परम पवित्र और श्री कृष्ण-भक्ति का आश्रय-स्थल, गोविंद-सागर के तट पर स्थित राधाकुंड को नमस्कार।

यत् तीरतः स्थितसमस्त-सुरासुराणां
पूजाविधिः प्रतिदिनं प्रसरत्यनन्तः।
तत् सौख्यदं तदमलं तदनन्त-कीर्तिं
राधाकुण्डं सुखकरं शरणं प्रपद्ये।।2।।

अर्थ: जिसके तट पर प्रतिदिन समस्त देव-असुरों की अनंत पूजा होती है, उस सुख-देने वाले, निर्मल और अनंत-कीर्ति संपन्न राधाकुंड की शरण लेता हूँ।

श्रीराधिकाप्रियतमस्य पदाम्बुजातं
यस्मिन् विलासरसिकस्य सदा विभाति।
राधाकुण्डं तदतुलं सुरसेव्यमानं
वन्दे मुदा भजति यत् सुजनो यतिश्च।।3।।

अर्थ: जिसमें श्रीराधिका के प्रियतम (कृष्ण) के चरणकमल सदा शोभित होते हैं, देवगण जिसकी सेवा करते हैं, उस अतुलनीय राधाकुंड को मैं प्रसन्नतापूर्वक वंदना करता हूँ।

त्वं राधिकाप्रियकरं मुकुटेन चित्र-
मालाभिरापि च परिष्कृतमप्यनन्तम्।
राधाकुण्डं भुवि सुपुण्यतमं समेत्य
वन्दे मुदा सुजनवन्दितपादपद्मम्।।4।।

अर्थ: राधिका को प्रिय, अनंत, पुण्यतम, सज्जनों द्वारा वंदित पादपद्म — इस राधाकुंड को मैं हर्षपूर्वक नमस्कार करता हूँ।

इति श्रीराधाकुण्ड अष्टकं सम्पूर्णम्।`,
