    deity: "भगवान रामचंद्र (मर्यादा पुरुषोत्तम)",
    deityInfo:
      "रामचंद्र भगवान विष्णु के सातवें अवतार हैं। उनका नाम 'राम' — अर्थात् रमण करने वाला — है। चंद्रमा जैसे शीतल और सौम्य स्वभाव के कारण 'रामचंद्र' कहलाते हैं। उनका जीवन आदर्श मानव-जीवन का प्रतीक है।",
    benefits:
      "श्री रामचंद्र अष्टकम के पाठ से मन में शीतलता और शांति आती है। क्रोध, अहंकार और कामना नष्ट होती है। राम-चंद्र की कृपा से जीवन में सत्य, धर्म और प्रेम की स्थापना होती है।",
    meaning: "",
    text: `रामचन्द्र रघुनन्दन भवभय-भंजन।
सीताराम रघुनाथ अखिल-जग-रंजन।।1।।

अर्थ: हे रामचंद्र! रघुनंदन, संसार के भय का नाश करने वाले, सीताराम, रघुनाथ, समस्त जगत को प्रसन्न करने वाले!

दशरथ-नन्दन जनक-दुलारे।
कौशल्या-सुत सुमित्रा-प्यारे।।2।।

अर्थ: दशरथ के नंदन, जनक के दुलारे, कौशल्या के पुत्र और सुमित्रा के प्रिय राम!

मंगल-भवन अमंगल-हारी।
द्रवहु सो दशरथ-अजिर-बिहारी।।3।।

अर्थ: (तुलसीदास) मंगलमय धाम, अमंगल दूर करने वाले, दशरथ के आंगन में विचरने वाले प्रभु, प्रसन्न हों।

राम चन्द्र कह करत तुलसी।
आरत जन मन हरत कुलिस सी।।4।।

अर्थ: तुलसीदास कहते हैं — रामचंद्र आर्त जनों के मन के कष्टों को वज्र की तरह काट देते हैं।

सीय-राम जय राम जय जय राम।
हरि अनन्त हरि-कथा अनन्ता।।5।।

अर्थ: सियाराम की जय! राम की जय! हरि अनंत हैं और उनकी कथा अनंत है।

रामचन्द्राष्टकं पुण्यं श्रद्धया यः पठेन्नरः।
सर्वपापैर्विनिर्मुक्तः रामधामं स गच्छति।।6।।

अर्थ: श्रद्धा से रामचंद्र अष्टकम पढ़ने वाला समस्त पापों से मुक्त होकर राम-धाम पाता है।

इति श्रीरामचंद्र अष्टकं सम्पूर्णम्।`,
