    deity: "भगवान नृसिंह",
    deityInfo:
      "भगवान नृसिंह विष्णु के चौथे अवतार हैं जिनका आधा शरीर सिंह का और आधा मनुष्य का है। उन्होंने हिरण्यकशिपु का वध करके प्रह्लाद की रक्षा की। षोडश बाहु नृसिंह सोलह भुजाओं वाले उग्र और करुणामय रूप हैं। वे भक्तों के परम रक्षक और भय-नाशक देवता हैं।",
