    text: `।। हरि शरण अष्टकम ।।

हरि शरणं हरि शरणं हरि शरणं मे सदा।
पापतापहर-स्वामिन् मुक्तिदायक देवता।।1।।

अर्थ: हे पाप और ताप हरने वाले स्वामी, मुक्तिदायक देव, हरि की शरण में आता हूँ, सदा हरि की शरण।

जन्म-मृत्यु-जरा-व्याधि भवसागर-भीरुकम्।
मां समुद्धर हे विष्णो त्वां शरणागतं विभो।।2।।

अर्थ: हे विष्णु, जन्म-मृत्यु-वृद्धावस्था-रोग और भव-सागर से भयभीत मुझ शरणागत का उद्धार कीजिए।

करुणाकर-वक्षोजा श्रीधर श्रीनिवास हे।
त्वत्पादाम्बुज-भक्तस्य मम पापं क्षमस्व च।।3।।

अर्थ: करुणाकर, वक्षस्थल में लक्ष्मी को धारण करने वाले, श्रीधर, श्रीनिवास, आपके चरण-कमलों के भक्त मेरे पाप क्षमा करें।

गरुडारूढ-देवाय शंखचक्रगदाधरे।
नमोस्तु पुण्डरीकाक्ष त्राहि मां शरणागतम्।।4।।

अर्थ: गरुड़ पर आरूढ़, शंख-चक्र-गदा धारण करने वाले, पुण्डरीकाक्ष को नमस्कार। मैं शरणागत हूँ, रक्षा करें।

अनाथनाथ-सर्वेश सर्वभूत-हितेश्वर।
नारायण महाविष्णो मम दुःखं निवर्तय।।5।।

अर्थ: अनाथों के नाथ, सर्वेश्वर, सर्व-प्राणियों के हित में लगे नारायण-महाविष्णु, मेरे दुख दूर करें।

प्रपन्नपाल-सौम्येश वैकुंठ-निलयप्रभो।
भवत्-प्रसाद-भाजिनं मां कुरुष्व जनार्दन।।6।।

अर्थ: शरणागतों के रक्षक, सौम्येश, वैकुंठ-निवासी प्रभु जनार्दन, मुझे आपकी कृपा का पात्र बनाइए।

कमलनाभ-देवेश लक्ष्मी-कान्त-परात्पर।
त्वन्नाम-स्मरणादेव पापजालं विनश्यति।।7।।

अर्थ: हे कमलनाभ, देवेश, लक्ष्मी-कान्त, परात्पर, आपके नाम के स्मरण मात्र से पापों का जाल नष्ट होता है।

हरि-शरणाष्टकमिदं यः पठेत् भक्तिमान् नरः।
सर्वपापविनिर्मुक्तः परमपदं लभेत् ध्रुवम्।।8।।

अर्थ: जो भक्तिपूर्वक हरि शरण अष्टकम का पाठ करे, वह सर्व पापों से मुक्त होकर निश्चित ही परमपद प्राप्त करता है।

इति हरि शरण अष्टकम सम्पूर्णम्।`,
