    text: `।। हिंगुलाज अष्टकम ।।

हिंगुले हिंगुले देवि कोट्टरीति च विश्रुते।
बलूच-प्रान्त-निवासिन्यै नमो हिंगलाजेश्वरि।।1।।

अर्थ: हे हिंगुला, कोट्टरी नाम से प्रसिद्ध देवी, बलूच प्रांत में निवास करने वाली हिंगलाजेश्वरी को नमस्कार।

एकावन्-शक्तिपीठेषु परमां स्थान-वासिनीम्।
सतीब्रह्मरन्ध्र-पाताद् आविर्भूतां नमाम्यहम्।।2।।

अर्थ: 51 शक्तिपीठों में परम स्थान वाली, सती के मस्तक के पतन से प्रकट हुई देवी को मैं प्रणाम करता हूँ।

सिंधु-तीर-समासीनां पर्वत-गुहा-निवासिनीम्।
चंद्र-सूर्य-प्रभामयीं वन्दे हिंगुलाजिकाम्।।3।।

अर्थ: सिंधु तट पर विराजित, पर्वत-गुफा में निवास करने वाली, चंद्र-सूर्य की कांति वाली हिंगुलाज को वंदन।

हिंदू-सिंधी-राजपूतैः सेव्यमाना महेश्वरी।
नवरात्रि-महापर्वे पूजिता लोकमातरे।।4।।

अर्थ: हिंदू, सिंधी, राजपूतों द्वारा सेव्य महेश्वरी, नवरात्रि के महापर्व में पूजित लोकमाता को नमस्कार।

रामचंद्र-वंदितायै गुरुनानक-प्रियायै च।
सर्वधर्म-समन्वित्रे नमो हिंगलाज-माते।।5।।

अर्थ: राम द्वारा वंदित, गुरुनानक को प्रिय, सर्वधर्म-समन्वयकारी हिंगलाज माता को नमस्कार।

मकराकार-यात्राभिः लक्षजन-समर्चिताम्।
तीर्थराज-स्वरूपायै नमो हिंगुला-देवतायै।।6।।

अर्थ: मकर संक्रांति यात्रा में लाखों लोगों द्वारा पूजित, तीर्थराज-स्वरूपिणी हिंगुला देवता को नमस्कार।

भवतापहारिण्यै च मुक्तिमार्ग-प्रदायिन्यै।
ज्वालारूप-धारिण्यै नमो हिंगुलजायिकायै।।7।।

अर्थ: भव-ताप हरने वाली, मुक्ति-मार्ग देने वाली, ज्वाला-रूपधारिणी हिंगुलाज को नमस्कार।

हिंगुलजाष्टकमेतत्तु यः पठेत् भक्तिसंयुतः।
शक्तिपीठ-फलं प्राप्य मोक्षमार्गे प्रयाति सः।।8।।

अर्थ: जो भक्तिपूर्वक हिंगुलाज अष्टकम का पाठ करे, वह शक्तिपीठ-दर्शन का फल पाकर मोक्षमार्ग पर अग्रसर होता है।

इति हिंगुलाज अष्टकम सम्पूर्णम्।`,
